import{_ as o,l as i,o as t,c as s,v as e,p as E,x as r,d as l,i as B,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"延迟套利","description":"","frontmatter":{"title":"延迟套利","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/latency-arbitrage.md","filePath":"quant/latency-arbitrage.md","lastUpdated":1789023840000}'),h={name:"quant/latency-arbitrage.md"};function d(A,a,u,c,m,g){const n=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="延迟套利" tabindex="-1">延迟套利 <a class="header-anchor" href="#延迟套利" aria-label="Permalink to &quot;延迟套利&quot;">​</a></h1><div class="epigraph"><p>在连续限价簿上，公共信息一到，过时报价会在一段极短的时间内变成免费期权；争夺这张期权的竞速，是市场设计问题，不是谁更勤快的问题。</p><footer>—— Budish, Cramton &amp; Shim, The High-Frequency Trading Arms Race, Quarterly Journal of Economics, 2015</footer></div><p>相关证券的价格在经济上应一起动：股指期货与 ETF、同一股票的多个交易场所、 mechanically 相连的现货与衍生品。公共信息到达之后，若市场仍按<strong>连续</strong>时间优先、价格优先撮合，总会有一小段窗口，某些报价还停在旧价值上。先看到新信息的一方可以与这些过时报价成交，把流动性提供者的报价当成被错误定价的期权。Budish、Cramton、Shim（2015）把这种机制叫做高频竞速的经济内核；后续 Aquilina、Budish、O&#39;Neill（2022）用交易所可观测的「竞速」消息来度量它的规模。本篇只写<strong>公开的市场结构文献</strong>：过时报价为何是连续交易的均衡产物、它如何以逆向选择的形式进入价差、以及频繁批次拍卖等设计回应。它不是交易手册。与 <a href="/quant/etf-arb">ETF 套利</a>、<a href="/quant/index-arb">指数套利</a> 的经济价差不同，这里的「套利」来自<strong>时间上的不一致</strong>，不是来自长期错误定价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书套利假设所有人同时面对同一价格向量。连续限价簿打破「同时」：撮合是一笔接一笔的，消息在物理与系统里传播需要时间，相关工具又在不同服务器上更新。于是出现一种与基本面无关的利润机会——<strong>延迟套利</strong>（latency arbitrage）：利用同一公共信息在不同订单簿上的到达差，去打仍按旧中点挂着的限价单。被打的一方往往是提供买卖报价的流动性供给者；他们事后发现成交发生在信息已经过时的价格上。</p><p>这与知情交易的经典逆向选择不同。Glosten–Milgrom 里知情者拥有关于价值的<strong>私有</strong>信号。延迟套利用的是<strong>已经公开</strong>、只是尚未均匀写进所有报价的信息：指数期货跳了，ETF 的卖价还在原地。经济上它仍是逆向选择——流动性供给者对「谁会来吃我的报价」的条件期望变差——但信息源是公共的，竞速对象是速度本身。若把这类亏损全部解释成「有人基本面研究得更好」，会误导监管与做市资本的讨论。</p><h3 id="连续时间优先如何把速度变成必要投入" tabindex="-1">连续时间优先如何把速度变成必要投入 <a class="header-anchor" href="#连续时间优先如何把速度变成必要投入" aria-label="Permalink to &quot;连续时间优先如何把速度变成必要投入&quot;">​</a></h3><p>价格优先、时间优先在连续时钟上意味着：同一价位，先到的单先成交。当公共信号使某档报价瞬间变成错价，所有想吃这档的人提交的是<strong>经济上相同</strong>的指令，胜负只取决于谁的消息与报单更先到达撮合引擎。这是一场对同一张被错误定价期权的竞速，而不是对分散估值的竞争。Budish 等人强调：只要相关价格的相关不是完美同步更新，连续簿就会内生出这种竞速；投入真实资源去缩短毫秒、微秒，在私人是理性的，在社会上却近似零和——更快的一方赢的是另一方本来也会提供的流动性租金，价格发现的增量很小。</p><p><span class="marginnote">文献里的「sniping / 抢跑过时报价」是均衡描述：公共信息到达后，过时限价单被市价或可立即成交的指令击中。它不是一份操作清单。讨论应停在机制与福利，而不是传播路径或机房位置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开研究度量延迟套利，靠的是<strong>可观测的市场数据与交易所消息</strong>，而不是任何人的专有链路。Budish 等用高度相关的工具（如 E-mini 与 SPY）在高频上的价格比较：当一边中间价已经移动、另一边报价尚未更新，错价的持续时长、发生频率、以及错价幅度构成「竞速的原料」。若错价经常出现、又迅速消失，且消失伴随着成交与报价撤销的密集爆发，就与「过时报价被吃或被撤」的叙事一致。</p><p>Aquilina、Budish、O&#39;Neill（2022）进一步使用交易所提供的、用于识别「同一时刻多笔可成交意图互相竞争」的消息结构，把竞速事件从普通成交里分开。他们关心的矩是：竞速在全部成交里占多少、竞速的价差租金有多大、流动性供给者因此必须把报价放宽多少才能盈亏平衡。这些是<strong>市场质量会计</strong>，用来回答「连续交易税了流动性多少」，不是用来复现某次竞速的胜负。</p><p>Foucault、Kozhan、Tham（2017）把跨市场的延迟套利写成「有毒套利」（toxic arbitrage）：当一边的价格已经包含信息、另一边的做市商还按旧信念报价，套利交易会伤害后者。毒性随工具间的相关、更新频率与信息不对称而变。这与本站 <a href="/quant/toxic-flow">毒性</a> 的订单流毒性是同一类逆向选择，只是信息来自另一张簿的公开印记，而不是来自个股的私有消息。</p><h3 id="相关工具、公共信息与过时报价" tabindex="-1">相关工具、公共信息与过时报价 <a class="header-anchor" href="#相关工具、公共信息与过时报价" aria-label="Permalink to &quot;相关工具、公共信息与过时报价&quot;">​</a></h3><p>设证券 A 与 B 的有效价值高度相关。A 先反映公共信息（更活跃的期货、更中心的场所），B 的限价单仍按旧中点挂着。经济上的错价是 \\(p_B-v(p_A)\\)。在连续簿里，这个错价的寿命由「B 侧做市商撤单」与「他人吃单」谁先完成决定。两者都是对同一公共信号的反应，于是形成竞速。批次拍卖若把极短区间内的指令集中撮合，同一信号上的指令同时到，时间优先不再分配那张免费期权，竞速的私人回报下降。</p><p>经验上应报告的是：相关结构（哪些合约在经济上是同一风险）、错价的分布、竞速成交相对普通成交的比例、以及价差、深度在信息密集时段的变化。不应把「A 领先 B」的领先滞后回归直接写成可交易规则：领先滞后本身随时钟精度、采样与通道延迟而变，Hasbrouck 信息份额文献已经说明时钟是识别条件。这里只需承认：在连续交易下，领先滞后的残差窗口会被竞速填满。</p><p><span class="marginnote">把期货与 ETF 的基差当成「延迟套利信号」会与基差的经济成分混在一起：利率、分红、创建赎回约束都会造成可持续的价差。延迟套利文献关心的是<strong>信息到达后数个最小时间单位内</strong>的过时报价，不是持有到收盘的基差交易。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>福利评价分三步。第一，流动性供给者预期会被公共信息下的过时报价伤害，于是事前加宽价差、变浅深度，把预期损失转给普通投资者。第二，竞速的胜者获得的是这笔转移，而不是新的风险分担；社会多出来的是为了争先而消耗的技术与通道资源。第三，价格发现并不因此显著变快：信息已经出现在领先工具上，落后工具的「发现」只是被强制对齐，连续撮合只是决定谁来执行这次对齐。Budish 等因此把高频竞速称为军备竞赛：私人最优速度不断上升，社会收益递减。</p><p>这与「做市商之间的竞争会压价差」不矛盾。竞争压的是<strong>处理与存货</strong>补偿；延迟套利加的是一层<strong>公共信息逆向选择</strong>。电子化可以同时让 \\(\\phi\\) 下降、让竞速更激烈。观察到价差下降，不能推出延迟套利消失；可能只是处理成本下降幅度更大。Menkveld 等对高频做市的综述指出：同一类快速参与者既在提供流动性，也在参与对过时报价的竞争；净效果取决于哪一种活动占主导，而不是取决于「是不是高频」。</p><p>市场设计的公开提案因此针对时钟，而不是针对某一类公司的身份。频繁批次拍卖（frequent batch auctions）把连续时间改成极短间隔的统一价格拍卖，使同一信息上的需求同时出清，时间优先不再奖励单纯的更快。离散化间隔的选择是设计参数：太长则中间价更新慢、价格发现变钝；太短则接近连续，竞速回来。文献讨论的是这个权衡，以及现有连续市场已经用的部分替代（随机延迟、速度bump、定期拍卖时段），它们改变的是过时报价的存活时间，从而改变那张免费期权的价值。</p><h3 id="与私有信息、中介利润的分界" tabindex="-1">与私有信息、中介利润的分界 <a class="header-anchor" href="#与私有信息、中介利润的分界" aria-label="Permalink to &quot;与私有信息、中介利润的分界&quot;">​</a></h3><p>延迟套利不是 PIN 里的信息事件，也不是公司内部人交易。它甚至不一定需要关于股票现金流的任何私有知识：只要看见领先合约的公开成交与报价即可。因此用 <a href="/quant/pin">PIN</a> 或公司公告窗口去「验证」延迟套利，问错了对象。它也不是指数套利里持有到收敛的那条腿：指数套利承担基差、分红与创建风险，延迟套利承担的是谁先到达的不确定性，持有期以市场的最小时间分辨率为单位。</p><p>对流动性供给者的含义是会计上的：实现价差在信息密集的竞速时段会变差，甚至为负；有效价差可能仍然看起来「有收入」，因为成交发生在宽报价上，但随后中点立刻跳走。这与 <a href="/quant/mrr-decomposition">MRR</a> 里 \\(\\theta\\) 上升、实现价差下降是同一类指纹，只是信息来源写成了「另一市场的公开价格」，而不是本市场订单流的意外。监管评估若只看平均价差，会把竞速税摊进全日均值里看不出来；应按信息到达聚类的窗口单独报告实现价差。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>文献的识别依赖时钟对齐与「何为同一信息」。把两个场所的本地接收时间当成交易所时间，会把管道延迟写成领先滞后，从而把普通的同步交易误判成延迟套利。研究应使用交易所时间戳，并承认时间戳精度本身构成分辨率上限。相关若不够高（不同到期、不同篮子、不同币种），「过时」没有定义：价差可能是风险溢价。</p><p>不要把所有高频盈利都叫做延迟套利。做市、库存管理、统计套利的慢信号、以及真正的私有信息，都会在高频数据里留下短持有期。延迟套利的定义性特征是：<strong>利润来自公共信息下过时限价单的免费期权，且竞争形式是对同一指令的时间优先竞速。</strong> 把任何快于某个人的交易都贴上这个标签，会让市场结构设计讨论失去对象。</p><p>本篇不讨论如何缩短路径、如何布置基础设施、如何撰写抢先指令。那些内容既不是定价理论，也不是可公开检验的市场质量度量。可公开讨论的是：连续交易是否内生竞速、竞速的租金有多大、以及改时钟规则会怎样改变价差与深度。后一个问题只能用设计对比与自然实验回答，不能用某一家公司的延迟数字回答。</p><p><span class="marginnote">Flash Boys 把竞速写进了公众叙事；学术文献要保留的是可证伪的机制：连续簿 + 相关工具 + 公共信息 → 过时报价期权 → 价差中的逆向选择。媒体里的人物与机房不是识别策略。</span></p>',29)),(t(),E(p,null,{default:r(()=>[B(n,{id:"mermaid-85",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%85%AC%E5%85%B1%E4%BF%A1%E6%81%AF%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20A%5B%22%E9%A2%86%E5%85%88%E5%B7%A5%E5%85%B7%E4%BB%B7%E6%A0%BC%E6%9B%B4%E6%96%B0%22%5D%0A%20%20PUB%20--%3E%20STALE%5B%22%E8%90%BD%E5%90%8E%E7%B0%BF%E4%B8%8A%E7%9A%84%E8%BF%87%E6%97%B6%E9%99%90%E4%BB%B7%E5%8D%95%22%5D%0A%20%20A%20--%3E%20RACE%5B%22%E8%BF%9E%E7%BB%AD%E6%97%B6%E9%97%B4%E4%BC%98%E5%85%88%E4%B8%8B%E7%9A%84%E7%AB%9E%E9%80%9F%22%5D%0A%20%20STALE%20--%3E%20RACE%0A%20%20RACE%20--%3E%20WIN%5B%22%E5%85%88%E5%88%B0%E8%80%85%E4%B8%8E%E8%BF%87%E6%97%B6%E6%8A%A5%E4%BB%B7%E6%88%90%E4%BA%A4%22%5D%0A%20%20RACE%20--%3E%20CXL%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E6%92%A4%E5%8D%95%22%5D%0A%20%20WIN%20--%3E%20AS%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%9B%E7%BB%99%E8%80%85%E7%9A%84%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%22%5D%0A%20%20AS%20--%3E%20SPR%5B%22%E4%BA%8B%E5%89%8D%E4%BB%B7%E5%B7%AE%E5%8A%A0%E5%AE%BD%E3%80%81%E6%B7%B1%E5%BA%A6%E5%8F%98%E6%B5%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>延迟套利在公开文献里指：公共信息下，连续限价簿上过时报价成为免费期权，时间优先把期权分配给速度竞争的胜者。</li><li>它是流动性供给者面临的公共信息逆向选择，会进入价差，不等于私有知情交易，也不等于持有基差至收敛的指数/ETF 套利。</li><li>度量应使用交易所时钟与可观测的竞速/错价事件，报告频率、租金与对实现价差的影响。</li><li>频繁批次拍卖等设计通过改时钟削弱「单纯更快」的私人回报；间隔长短是发现速度与竞速税之间的权衡。</li><li>讨论停留在机制、福利与市场质量；不涉及基础设施或指令实现。</li><li>出处：Budish, Cramton &amp; Shim, <em>QJE</em>, 2015；度量见 Aquilina, Budish &amp; O&#39;Neill, <em>QJE</em>, 2022；跨市场毒性见 Foucault, Kozhan &amp; Tham, 2017。</li></ul>',2))])}const f=o(h,[["render",d]]);export{q as __pageData,f as default};
